/**
 * The whole thread for one issue, in reading order: top-level comments oldest
 * first and, under each one, every reply that descends from it — directly or
 * through other replies — in posting order. A deleted comment stays in place
 * as a placeholder with its text removed, so the replies under it do too.
 */
export async function listThread(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  const rows = getDb()
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
      ),
    )
    .orderBy(asc(comments.createdAt), asc(comments.id))
    .all();

  const decorated: CommentWithAuthor[] = rows.map((row) => {
    const comment = toComment(row.comment);
    return {
      ...comment,
      body: comment.archivedAt === null ? comment.body : "",
      author: toUser(row.author),
    };
  });

  const byId = new Map(decorated.map((comment) => [comment.id, comment]));

  const repliesBy = new Map<string, CommentWithAuthor[]>();
  for (const comment of decorated) {
    const rootId = threadRootId(comment, byId);
    if (rootId === null || rootId === comment.id) continue;
    const bucket = repliesBy.get(rootId) ?? [];
    bucket.push(comment);
    repliesBy.set(rootId, bucket);
  }

  return decorated
    .filter((comment) => comment.parentId === null)
    .map((comment) => ({
      comment,
      replies: repliesBy.get(comment.id) ?? [],
    }));
}

/** The top-level comment this row hangs from, walking parent links. */
function threadRootId(
  comment: CommentWithAuthor,
  byId: ReadonlyMap<string, CommentWithAuthor>,
): string | null {
  let current = comment;
  const seen = new Set<string>();
  while (current.parentId !== null) {
    if (seen.has(current.id)) return null;
    seen.add(current.id);
    const parent = byId.get(current.parentId);
    if (parent === undefined) return null;
    current = parent;
  }
  return current.id;
}

