        href: `/issues/${payload.issueId}`,
        actorId: payload.actorId,
      },
    );
  }
});

input.new_string:
subscribe("comment.created", async (payload) => {
  const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
  const comment = await commentRepo.findCommentById(
    payload.orgId,
    payload.commentId,
  );
  const parent =
    comment?.parentId === null || comment?.parentId === undefined
      ? null
      : await commentRepo.findCommentById(payload.orgId, comment.parentId);

  const mentioned = new Set(payload.mentionedUserIds);
  const commentRecipients: UserId[] = [];
  if (issue) {
    commentRecipients.push(issue.authorId);
    if (issue.assigneeId) commentRecipients.push(issue.assigneeId);
  }
  if (parent) commentRecipients.push(parent.authorId);

  // A mention alert takes precedence, and each person hears about the
  // comment at most once. The author is dropped inside `notify`.
  const commentOnly = commentRecipients.filter(
    (userId) => !mentioned.has(userId),
  );

  await notify(payload.orgId, "comment_created", commentOnly, {
    title: "New comment",
    body: `A comment was added to issue ${payload.issueId}`,
    href: `/issues/${payload.issueId}`,
    actorId: payload.actorId,
  });

  if (payload.mentionedUserIds.length > 0) {
    await notify(
      payload.orgId,
      "comment_mention",
      payload.mentionedUserIds,
      {
        title: "You were mentioned",
        body: `You were mentioned on issue ${payload.issueId}`,
        href: `/issues/${payload.issueId}`,
        actorId: payload.actorId,
      },
    );
  }
});

